-- Model: lnk_company_company_parentid__company_hkey_curr
-- Description: Current active relationship for LNK_COMPANY_COMPANY_PARENTID using ROW_NUMBER()
-- Generated by: bv pipeline generate transform
-- Link Type: RELATIONSHIP_BASED_LINK

WITH RANKED_RELATIONSHIPS AS (
SELECT
    l.LNK_COMPANY_COMPANY_PARENTID_HKEY AS LNK_COMPANY_COMPANY_PARENTID_HKEY,
    l.COMPANY_HKEY AS COMPANY_HKEY,
    l.COMPANY_PARENTID_HKEY AS COMPANY_PARENTID_HKEY,

    -- TODO: use generated tag instead of well-known name _CURRENT_ACTIVE_TIMESTAMP
    ls._CURRENT_ACTIVE_TIMESTAMP AS _CURRENT_RELATIONSHIP_TIMESTAMP, -- was ls._AIRBYTE_EXTRACTED_AT

    ROW_NUMBER() OVER (
        PARTITION BY l.COMPANY_HKEY -- parent hub hk
        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls._AIRBYTE_EXTRACTED_AT
    ) AS row_num

FROM {{ source('eli_dv_rv', 'lnk_company_company_parentid') }} l
INNER JOIN {{ ref('lks_ssc_company_company_parentid_curr') }} ls
    ON l.LNK_COMPANY_COMPANY_PARENTID_HKEY = ls.LNK_COMPANY_COMPANY_PARENTID_HKEY
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RELATIONSHIPS
WHERE row_num = 1
